import '@fontsource/ibm-plex-mono/400.css'
import '@fontsource/ibm-plex-mono/500.css'
import '@fontsource/space-grotesk/400.css'
import '@fontsource/space-grotesk/500.css'
import '@fontsource/space-grotesk/600.css'
import './style.css'
import { World } from './scene.js'
import {
  GENES, STAT_KEYS, STAT_META, phenotype, statsOf, maxHpOf, maxStaminaOf,
  movesFor, randomGenome, freshNeeds, generateStarter, makeName, sexOf,
  breedGenomes, geneticSimilarity, decayNeeds, formatAge, dnaSequence,
} from './dna.js'

const $ = (selector, root = document) => root.querySelector(selector)
const esc = value => String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c])
const clamp = (n, low, high) => Math.max(low, Math.min(high, n))
const stateKey = 'helix-forge-save-v1'

function loadGame() {
  try {
    const saved = JSON.parse(localStorage.getItem(stateKey))
    if (saved?.creatures?.length) {
      saved.creatures.forEach(c => { c.needs ||= freshNeeds(78); c.wins ||= 0; c.battles ||= 0 })
      return { creatures: saved.creatures, selected: saved.selected || saved.creatures[0].id, coins: saved.coins ?? 120, food: saved.food ?? 8, wins: saved.wins ?? 0, lastSaved: Date.now() }
    }
  } catch (error) { console.warn('Could not load save', error) }
  const creatures = [
    generateStarter(401, { hueA: 0.73, hueB: 0.22, horns: 0.76, muscle: 0.64, size: 0.58, brain: 0.45, speed: 0.56 }),
    generateStarter(908, { hueA: 0.12, hueB: 0.83, wings: 0.81, speed: 0.74, brain: 0.68, horns: 0.25, size: 0.42 }),
    generateStarter(173, { hueA: 0.47, hueB: 0.1, armor: 0.79, bone: 0.78, size: 0.77, muscle: 0.55, wings: 0.1 }),
  ]
  creatures[0].name = 'Cinderhorn'
  creatures[1].name = 'Glimmerwing'
  creatures[2].name = 'Mossback'
  creatures[0].needs = freshNeeds(88)
  creatures[1].needs = freshNeeds(74)
  creatures[2].needs = freshNeeds(81)
  return { creatures, selected: creatures[0].id, coins: 120, food: 8, wins: 0, lastSaved: Date.now() }
}

const game = loadGame()
let world
let mode = 'habitat'
let activeTab = 'overview'
let battle = null
let toastTimer
let lastFrame = performance.now()
let dirty = true

const app = $('#app')
app.innerHTML = `
  <div class="shell">
    <header class="topbar">
      <a class="brand" href="#" aria-label="Helix Forge home"><span class="brand-mark">H<span>↗</span></span><span class="brand-copy">HELIX<span>FORGE</span></span></a>
      <div class="top-status"><span class="live-dot"></span><span>GENOME SANCTUARY</span><span class="season">SEASON 01 <i>·</i> THE VERDANT</span></div>
      <div class="resources"><div class="resource"><span class="resource-icon">✧</span><b id="coin-count">120</b><small>SHARDS</small></div><div class="resource"><span class="resource-icon food-icon">◉</span><b id="food-count">8</b><small>NECTAR</small></div><button class="icon-btn" id="sound-toggle" title="Toggle ambience" aria-label="Toggle ambience">♫</button></div>
    </header>
    <main class="workspace">
      <aside class="left-rail">
        <div class="section-label">YOUR SANCTUARY <span id="roster-count">03</span></div>
        <div class="roster" id="roster"></div>
        <button class="add-creature" id="new-creature"><span>＋</span> DISCOVER CREATURE <kbd>120 ✧</kbd></button>
        <div class="rail-spacer"></div>
        <div class="sanctuary-card"><div class="sanctuary-orb">✳</div><div><b>THE HOLLOW</b><span>Habitat level 01</span></div><span class="online-tag">LIVE</span><p>Your creatures wander, rest and recover here.</p><div class="habitat-meter"><i></i></div><small>SANCTUARY HARMONY <b>78%</b></small></div>
        <div class="rail-footer"><span>BUILD 1.0.4</span><span>◆ AUTOSAVED</span></div>
      </aside>
      <section class="stage-column">
        <div class="stage-head"><div><div class="eyebrow" id="stage-kicker"><span class="eyebrow-line"></span> OPEN HABITAT</div><h1 id="stage-title">The Verdant Hollow</h1></div><div class="stage-controls"><span class="creature-count"><i></i><b id="stage-count">3</b> CREATURES</span><button class="view-btn active" id="habitat-btn">◉ <span>HABITAT</span></button><button class="view-btn" id="arena-btn">⚔ <span>ARENA</span></button></div></div>
        <div class="viewport-wrap"><div class="viewport" id="viewport"></div><div class="viewport-vignette"></div><div class="scene-tag"><span class="live-dot"></span><span id="scene-tag-text">ECOSYSTEM ACTIVE</span></div><div class="camera-hint">DRAG TO ORBIT <span>·</span> SCROLL TO ZOOM</div><div id="battle-hud" class="battle-hud hidden"></div><div id="battle-result" class="battle-result hidden"></div></div>
        <div class="stage-bottom"><div class="world-note"><span class="note-icon">✦</span><span><b>THE HOLLOW IS ALIVE</b><small>Creatures' traits and temperament are written in their DNA.</small></span></div><div class="stage-actions"><button class="secondary-btn" id="breed-shortcut">♧ <span>BREED</span></button><button class="primary-btn" id="battle-shortcut">⚔ <span>ENTER ARENA</span><b>↗</b></button></div></div>
      </section>
      <aside class="right-panel" id="right-panel"></aside>
    </main>
    <div class="mobile-nav"><button data-mobile="sanctuary">◈<span>Sanctuary</span></button><button data-mobile="habitat" class="selected">◉<span>Habitat</span></button><button data-mobile="profile">◎<span>Profile</span></button></div>
    <div class="toast" id="toast" role="status"></div>
    <div class="modal-layer hidden" id="modal-layer"><div class="modal" id="modal"></div></div>
  </div>`

const viewport = $('#viewport')
world = new World(viewport, {
  onSelect: id => selectCreature(id),
  onBackground: () => { if (mode === 'habitat') toast('Select a creature to inspect its genome.') },
})

function persist() {
  localStorage.setItem(stateKey, JSON.stringify({ creatures: game.creatures, selected: game.selected, coins: game.coins, food: game.food, wins: game.wins }))
  $('#coin-count').textContent = game.coins
  $('#food-count').textContent = game.food
}
function selectedCreature() { return game.creatures.find(c => c.id === game.selected) || game.creatures[0] }
function selectedName() { return selectedCreature()?.name || 'Creature' }
function toast(message) {
  const el = $('#toast'); el.textContent = message; el.classList.add('show')
  clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('show'), 2600)
}
function selectCreature(id) {
  if (!game.creatures.some(c => c.id === id)) return
  game.selected = id
  world.setSelected(id)
  dirty = true
  renderRoster(); renderProfile(); persist()
}
function addToWorld() {
  world.clearCreatures()
  const positions = [[-2.7, 0, 0.5], [0.4, 0, -1.5], [2.4, 0, 1.7], [-1.4, 0, 3.2], [3.2, 0, -2.3], [0, 0, 2.8]]
  game.creatures.forEach((c, i) => world.addCreature(c, { position: positions[i % positions.length], rotation: i * 1.9 }))
  world.setSelected(game.selected)
}
function renderRoster() {
  const roster = $('#roster')
  roster.innerHTML = game.creatures.map((c, i) => {
    const p = phenotype(c.genome), stats = statsOf(c), active = c.id === game.selected
    const needs = Object.values(c.needs).reduce((a, b) => a + b, 0) / 4
    return `<button class="roster-card ${active ? 'selected' : ''}" data-creature="${esc(c.id)}"><span class="roster-num">0${i + 1}</span><span class="roster-avatar" style="--creature-color:${p.bodyColor};--creature-accent:${p.accentColor}"><span class="avatar-eye"></span></span><span class="roster-info"><b>${esc(c.name)}</b><small>GEN ${c.generation || 0} <i>·</i> ${c.sex === 'F' ? '♀' : '♂'}</small><span class="roster-mini"><i style="width:${needs}%"></i></span></span><span class="roster-rating">${stats.power}</span></button>`
  }).join('')
  roster.querySelectorAll('[data-creature]').forEach(el => el.addEventListener('click', () => selectCreature(el.dataset.creature)))
  $('#roster-count').textContent = String(game.creatures.length).padStart(2, '0')
  $('#stage-count').textContent = game.creatures.length
  $('#stage-count').parentElement.style.display = mode === 'habitat' ? '' : 'none'
}

function bar(value, color, label) {
  return `<div class="stat-row"><span>${label}</span><div class="bar-track"><i style="width:${clamp(value, 0, 100)}%;background:${color}"></i></div><b>${Math.round(value)}</b></div>`
}
function renderProfile() {
  const c = selectedCreature()
  if (!c) return
  const p = phenotype(c.genome), stats = statsOf(c)
  const needs = [['Hunger', c.needs.hunger, '🥩'], ['Energy', c.needs.energy, '☾'], ['Hygiene', c.needs.hygiene, '✧'], ['Enrichment', c.needs.fun, '♡']]
  const tabBody = activeTab === 'genome' ? renderGenome(c) : activeTab === 'moves' ? renderMoves(c) : renderOverview(c, p, stats, needs)
  $('#right-panel').innerHTML = `
    <div class="profile-heading"><div><div class="eyebrow"><span class="eyebrow-line"></span> CREATURE DOSSIER</div><h2>FIELD NOTES</h2></div><button class="icon-btn more-btn" id="profile-more" aria-label="Creature options">···</button></div>
    <div class="identity"><div class="identity-art" style="--creature-color:${p.bodyColor};--creature-accent:${p.accentColor}"><span class="art-glow"></span><span class="art-creature"><i class="art-ear"></i><i class="art-eye"></i><i class="art-horn"></i><i class="art-tail"></i></span><span class="art-label">SPECIMEN 0${game.creatures.indexOf(c) + 1}</span><span class="rarity">${p.horns > .72 || p.wings > .75 ? '✦ RARE' : '◈ COMMON'}</span></div><div class="identity-copy"><div class="name-line"><h3>${esc(c.name)}</h3><span class="sex-badge">${c.sex === 'F' ? '♀' : '♂'}</span></div><p>${c.generation ? `Generation ${c.generation} · offspring` : 'Foundling · Verdant Hollow'}</p><div class="trait-pills"><span>${p.horns > .62 ? 'HORNED' : p.wings > .62 ? 'WINGED' : p.armor > .62 ? 'ARMORED' : 'ADAPTIVE'}</span><span>LV ${Math.min(99, 1 + c.wins)}</span></div></div></div>
    <div class="profile-tabs"><button data-tab="overview" class="${activeTab === 'overview' ? 'active' : ''}">OVERVIEW</button><button data-tab="genome" class="${activeTab === 'genome' ? 'active' : ''}">GENOME <span>20</span></button><button data-tab="moves" class="${activeTab === 'moves' ? 'active' : ''}">ABILITIES</button></div>
    <div class="profile-content">${tabBody}</div>
    <div class="profile-footer"><button class="care-btn" data-care="feed"><span>◉</span><b>FEED</b><small>1 NECTAR</small></button><button class="care-btn" data-care="play"><span>♡</span><b>PLAY</b><small>+FUN</small></button><button class="care-btn" data-care="rest"><span>☾</span><b>REST</b><small>+ENERGY</small></button></div>`
  $('#right-panel').querySelectorAll('[data-tab]').forEach(el => el.addEventListener('click', () => { activeTab = el.dataset.tab; renderProfile() }))
  $('#right-panel').querySelectorAll('[data-care]').forEach(el => el.addEventListener('click', () => care(el.dataset.care)))
  $('#profile-more').addEventListener('click', () => creatureMenu(c))
}

function renderOverview(c, p, stats, needs) {
  const needsMarkup = needs.map(([label, value, icon]) => `<div class="need-row"><span class="need-icon">${icon}</span><span class="need-name">${label}</span><span class="need-track"><i style="width:${value}%;background:${value < 28 ? '#ff7a72' : value < 55 ? '#ffc36a' : '#77e6bf'}"></i></span><b>${Math.round(value)}%</b></div>`).join('')
  return `<section class="panel-block needs-block"><div class="block-heading"><span>VITAL SIGNS</span><span class="tiny-status"><i></i> STABLE</span></div>${needsMarkup}</section>
  <section class="panel-block"><div class="block-heading"><span>GENETIC POTENTIAL</span><button class="text-action" data-open-tab="genome">VIEW DNA ↗</button></div>
  ${bar(stats.power, '#d7fa77', 'ABILITY')}${bar(stats.bones, '#f2cb77', 'BONES')}${bar(stats.mobility, '#71d9db', 'MOBILITY')}${bar(stats.brain, '#b9a4f5', 'INTELLECT')}
  </section><section class="temperament"><div class="temper-icon">✺</div><div><b>INSTINCT PROFILE</b><p>${p.brain > .67 ? 'A keen strategist with a curious streak.' : p.speed > .67 ? 'Restless and quick to answer a challenge.' : p.muscle > .68 ? 'A bold powerhouse who thrives on action.' : 'An adaptable soul, ready to find its own path.'}</p></div></section>
  <div class="record-line"><span>RECORD <b>${c.wins || 0}W — ${Math.max(0, (c.battles || 0) - (c.wins || 0))}L</b></span><span>AGE <b>${formatAge(c.born)}</b></span></div>`
}
function renderGenome(c) {
  const grouped = { frame: 'FRAME', limb: 'LIMBS', weapon: 'ADAPTATIONS', core: 'CORE', coat: 'PIGMENT' }
  return `<div class="genome-summary"><div><small>DNA SEQUENCE</small><b>${dnaSequence(c.genome).slice(0, 19)}…</b></div><span>GEN ${c.generation || 0}</span></div>${Object.entries(grouped).map(([group, label]) => `<section class="gene-group"><div class="gene-group-title">${label}<span>${GENES.filter(g => g.group === group).length} LOCI</span></div>${GENES.filter(g => g.group === group).map(g => { const [a, b] = c.genome[g.key]; const v = (a + b) / 2; return `<div class="gene-line"><span title="${g.desc}">${g.label}</span><span class="alleles"><i style="width:${a * 100}%"></i><i style="width:${b * 100}%"></i></span><b>${Math.round(v * 100)}</b></div>` }).join('')}</section>`).join('')}`
}
function renderMoves(c) {
  return `<div class="ability-intro"><span>DNA-EXPRESSED ABILITIES</span><small>${movesFor(c).length} UNLOCKED</small></div>${movesFor(c).map((move, i) => `<article class="move-card"><div class="move-icon ${move.type}">${move.icon}</div><div class="move-info"><div><b>${esc(move.name)}</b><span class="move-tag">${move.tag}</span></div><p>${esc(move.desc)}</p><div class="move-meta"><span>${move.type === 'defend' ? 'RECOVERY' : `POWER ${Math.round(move.power * 34)}`}</span><span>COST ${Math.max(0, move.cost)} STA</span></div></div></article>`).join('')}<div class="ability-note">Abilities emerge from expressed traits. Breed for new combinations.</div>`
}
function care(action) {
  const c = selectedCreature()
  if (action === 'feed') {
    if (game.food < 1) return toast('You are out of nectar. Discover a creature to restock.')
    if (c.needs.hunger > 94) return toast(`${c.name} is already full.`)
    game.food--; c.needs.hunger = clamp(c.needs.hunger + 38, 0, 100); c.needs.energy = clamp(c.needs.energy + 5, 0, 100)
    toast(`${c.name} enjoyed a nectar fruit. +38 hunger`)
  } else if (action === 'play') {
    if (c.needs.energy < 12) return toast(`${c.name} is too tired to play. Let them rest.`)
    c.needs.fun = clamp(c.needs.fun + 30, 0, 100); c.needs.energy = Math.max(0, c.needs.energy - 8)
    toast(`${c.name} had a lovely play session. +30 enrichment`)
  } else {
    c.needs.energy = clamp(c.needs.energy + 36, 0, 100); c.needs.hygiene = clamp(c.needs.hygiene + 8, 0, 100)
    toast(`${c.name} took a restorative nap. +36 energy`)
  }
  dirty = true; persist(); renderProfile(); renderRoster()
}

