44: const viewport = $('#viewport')
45: world = new World(viewport, { onSelect: selectCreature, onBackground: () => mode === 'habitat' && toast('Select a creature to inspect its genome.') })
46: 
47: function persist() {
48:   try { localStorage.setItem(SAVE, JSON.stringify({ creatures: game.creatures, selected: game.selected, coins: game.coins, food: game.food, wins: game.wins })) } catch (e) { console.warn('Save failed', e) }
49:   $('#coins').textContent = game.coins; $('#food').textContent = game.food
50: }
51: function selected() { return game.creatures.find(c => c.id === game.selected) || game.creatures[0] }
52: function toast(text) { const el = $('#toast'); el.textContent = text; el.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('show'), 2600) }
53: function selectCreature(id) { if (!game.creatures.some(c => c.id === id)) return; game.selected = id; world.setSelected(id); renderRoster(); renderProfile(); persist() }
54: function populateWorld() {
55:   world.clearCreatures()
56:   const spots = [[-2.7,0,.5],[.4,0,-1.5],[2.4,0,1.7],[-1.4,0,3.2],[3.2,0,-2.3],[0,0,2.8]]
57:   game.creatures.forEach((c,i) => world.addCreature(c, { position: spots[i % spots.length], rotation: i * 1.9 }))
58:   world.setSelected(game.selected)
59: }
60: function renderRoster() {
61:   $('#roster').innerHTML = game.creatures.map((c,i) => {
62:     const p = phenotype(c.genome), vitality = Object.values(c.needs).reduce((a,b) => a+b,0)/4
63:     return `<button class="roster-card ${c.id === game.selected ? 'selected' : ''}" data-creature="${esc(c.id)}"><span class="roster-num">0${i+1}</span><span class="roster-avatar" style="--creature-color:${p.bodyColor};--creature-accent:${p.accentColor}"><i></i></span><span class="roster-info"><b>${esc(c.name)}</b><small>GEN ${c.generation || 0} <i>·</i> ${c.sex === 'F' ? '♀' : '♂'}</small><span class="roster-mini"><i style="width:${vitality}%"></i></span></span><span class="roster-rating">${statsOf(c).power}</span></button>`
64:   }).join('')
65:   $('#roster-count').textContent = String(game.creatures.length).padStart(2,'0'); $('#stage-count').textContent = game.creatures.length
66: }
67: function statBar(label, value, color) { return `<div class="stat-row"><span>${label}</span><div class="bar-track"><i style="width:${clamp(value,0,100)}%;background:${color}"></i></div><b>${Math.round(value)}</b></div>` }
68: function renderProfile() {
69:   const c = selected(); if (!c) return
70:   const p = phenotype(c.genome), stats = statsOf(c), genes = GENES
71:   const body = tab === 'genome' ? renderGenome(c) : tab === 'abilities' ? renderAbilities(c) : renderOverview(c,p,stats)
72:   const combat = mode === 'arena' && battle && !battle.finished && c.id === battle.player.id ? `<section class="combat-actions"><div class="block-heading"><span>CHOOSE YOUR MOVE</span><small>${battle.busy?'TURN IN PROGRESS':'YOUR TURN'}</small></div><div class="combat-grid">${movesFor(c).map(m=>`<button data-move="${m.id}" ${battle.busy?'disabled':''}><b>${m.icon} ${esc(m.name)}</b><small>${m.type==='defend'?`+${Math.abs(m.cost)} STA`:`${Math.max(0,m.cost)} STA · ${Math.round((m.power||0)*20)} PWR`}</small></button>`).join('')}</div></section>` : ''
73:   const trait = p.horns > .62 ? 'HORNED' : p.wings > .62 ? 'WINGED' : p.armor > .62 ? 'ARMORED' : 'ADAPTIVE'
74:   $('#right-panel').innerHTML = `<div class="profile-heading"><div><div class="eyebrow">CREATURE DOSSIER</div><h2>FIELD NOTES</h2></div><button class="icon-btn" data-action="rename" title="Rename creature">···</button></div>
75:   <div class="identity"><div class="identity-art" style="--creature-color:${p.bodyColor};--creature-accent:${p.accentColor}"><span class="art-creature"><i class="art-tail"></i><i class="art-horn"></i><i class="art-eye"></i></span><small>SPECIMEN 0${game.creatures.indexOf(c)+1}</small><b>${p.horns > .72 || p.wings > .75 ? '✦ RARE' : '◈ COMMON'}</b></div><div class="identity-copy"><div class="name-line"><h3>${esc(c.name)}</h3><span>${c.sex === 'F' ? '♀' : '♂'}</span></div><p>${c.generation ? `Generation ${c.generation} · offspring` : 'Foundling · Verdant Hollow'}</p><div class="trait-pills"><span>${trait}</span><span>LV ${Math.min(99,1+(c.wins||0))}</span></div></div></div>
76:   <div class="profile-tabs"><button data-tab="overview" class="${tab==='overview'?'active':''}">OVERVIEW</button><button data-tab="genome" class="${tab==='genome'?'active':''}">GENOME <i>20</i></button><button data-tab="abilities" class="${tab==='abilities'?'active':''}">ABILITIES</button></div><div class="profile-content">${body}</div>${combat}
77:   <div class="profile-footer"><button class="care-btn" data-care="feed"><span>◉</span><b>FEED</b><small>1 NECTAR</small></button><button class="care-btn" data-care="play"><span>♡</span><b>PLAY</b><small>+FUN</small></button><button class="care-btn" data-care="rest"><span>☾</span><b>REST</b><small>+ENERGY</small></button></div>`
78: }
79: function renderOverview(c,p,s) {
80:   const needs = [['Hunger',c.needs.hunger,'🥩'],['Energy',c.needs.energy,'☾'],['Hygiene',c.needs.hygiene,'✧'],['Enrichment',c.needs.fun,'♡']]
81:   return `<section class="panel-block"><div class="block-heading"><span>VITAL SIGNS</span><b class="stable"><i></i> STABLE</b></div>${needs.map(([n,v,icon])=>`<div class="need-row"><span class="need-icon">${icon}</span><span class="need-name">${n}</span><span class="need-track"><i style="width:${v}%;background:${v<28?'#ff7a72':v<55?'#ffc36a':'#77e6bf'}"></i></span><b>${Math.round(v)}%</b></div>`).join('')}</section>
82:   <section class="panel-block"><div class="block-heading"><span>GENETIC POTENTIAL</span><button class="text-action" data-tab="genome">VIEW DNA ↗</button></div>${statBar('ABILITY',s.power,'#d7fa77')}${statBar('BONES',s.bones,'#f2cb77')}${statBar('MOBILITY',s.mobility,'#71d9db')}${statBar('INTELLECT',s.brain,'#b9a4f5')}</section>
83:   <section class="temperament"><span>✺</span><div><b>INSTINCT PROFILE</b><p>${p.brain>.67?'A keen strategist with a curious streak.':p.speed>.67?'Restless and quick to answer a challenge.':p.muscle>.68?'A bold powerhouse who thrives on action.':'An adaptable soul, ready to find its own path.'}</p></div></section><div class="record-line"><span>RECORD <b>${c.wins||0}W — ${Math.max(0,(c.battles||0)-(c.wins||0))}L</b></span><span>AGE <b>${formatAge(c.born)}</b></span></div>`
84: }
85: function renderGenome(c) {
86:   const groups = { frame:'FRAME', limb:'LIMBS', weapon:'ADAPTATIONS', core:'CORE', coat:'PIGMENT' }
87:   return `<div class="genome-summary"><small>DNA SEQUENCE<br><b>${dnaSequence(c.genome).slice(0,22)}…</b></small><span>GEN ${c.generation||0}</span></div>${Object.entries(groups).map(([group,label])=>`<section class="gene-group"><div class="gene-group-title">${label}<span>${GENES.filter(g=>g.group===group).length} LOCI</span></div>${GENES.filter(g=>g.group===group).map(g=>{const [a,b]=c.genome[g.key];return `<div class="gene-line" title="${esc(g.desc)}"><span>${g.label}</span><span class="alleles"><i style="width:${a*100}%"></i><i style="width:${b*100}%"></i></span><b>${Math.round((a+b)*50)}</b></div>`}).join('')}</section>`).join('')}`
88: }
89: function renderAbilities(c) {
90:   const moves = movesFor(c)
91:   return `<div class="ability-intro"><span>DNA-EXPRESSED ABILITIES</span><small>${moves.length} UNLOCKED</small></div>${moves.map(m=>`<article class="move-card"><div class="move-icon ${m.type}">${m.icon}</div><div class="move-info"><div><b>${esc(m.name)}</b><span>${m.tag}</span></div><p>${esc(m.desc)}</p><small>${m.type==='defend'?'RECOVERY':`POWER ${Math.round(m.power*34)}`} · COST ${Math.max(0,m.cost)} STA</small></div></article>`).join('')}<div class="ability-note">Abilities emerge from expressed traits. Breed for new combinations.</div>`
92: }
93: function care(action) {
94:   const c=selected()
95:   if(action==='feed') { if(game.food<1)return toast('You are out of nectar. Discover a creature to restock.'); if(c.needs.hunger>94)return toast(`${c.name} is already full.`); game.food--; c.needs.hunger=clamp(c.needs.hunger+38,0,100); c.needs.energy=clamp(c.needs.energy+5,0,100); toast(`${c.name} enjoyed a nectar fruit.`) }
96:   else if(action==='play') { if(c.needs.energy<12)return toast(`${c.name} is too tired to play. Let them rest.`); c.needs.fun=clamp(c.needs.fun+30,0,100); c.needs.energy=Math.max(0,c.needs.energy-8); toast(`${c.name} had a lovely play session.`) }
97:   else { c.needs.energy=clamp(c.needs.energy+36,0,100); c.needs.hygiene=clamp(c.needs.hygiene+8,0,100); toast(`${c.name} took a restorative nap.`) }
98:   persist(); renderProfile(); renderRoster()
99: }
100: function showModal(content) { $('#modal').innerHTML=content; $('#modal-layer').classList.remove('hidden') }
101: function closeModal() { $('#modal-layer').classList.add('hidden') }
102: function discover() {
103:   if(game.coins<60)return toast('You need 60 shards to discover a creature.')
104:   game.coins-=60
105:   const c=generateStarter(Math.floor(Math.random()*100000),{}); c.needs=freshNeeds(82)
106:   game.creatures.push(c); game.selected=c.id; if(mode==='habitat') { world.addCreature(c,{position:[(Math.random()-.5)*5,0,(Math.random()-.5)*5]}); world.setSelected(c.id) }
107:   persist(); renderRoster(); renderProfile(); toast(`${c.name} joined your sanctuary.`)
108: }
109: function breedDialog() {
110:   if(game.creatures.length<2)return toast('You need two creatures to breed.')
111:   const a=selected(), others=game.creatures.filter(c=>c.id!==a.id)
112:   showModal(`<button class="modal-close" data-action="close">×</button><div class="eyebrow">INHERITANCE LAB · GEN 0${(a.generation||0)+1}</div><h2>Pair a lineage</h2><p>Choose a second parent. Their expressed traits combine with ${esc(a.name)}'s DNA; mutation can create new adaptations.</p><div class="parent-preview"><div class="parent-chip"><i style="--creature-color:${phenotype(a.genome).bodyColor}"></i><span><b>${esc(a.name)}</b><small>SELECTED PARENT</small></span></div><span class="cross">×</span><select id="mate-select">${others.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${c.sex==='F'?'♀':'♂'} · GEN ${c.generation||0}</option>`).join('')}</select></div><div class="modal-actions"><button class="secondary-btn" data-action="close">CANCEL</button><button class="primary-btn" data-action="breed-confirm">CREATE OFFSPRING ↗</button></div>`)
