173:   world.burst?.({x:attacker==='player'?2: -2,y:1.5,z:.3},phenotype(battle[attacker].genome).accentColor,15)
174:   toast(`${move.name} dealt ${damage} damage.`)
175:   if(move.buff==='evade')battle.guard[attacker]=true
176:   done()
177: }
178: function playerTurn(moveId) {
179:   if(!battle||battle.busy||battle.finished)return
180:   const move=movesFor(battle.player).find(m=>m.id===moveId); if(!move)return
181:   battle.busy=true; renderBattle()
182:   applyMove('player','foe',move,()=>{
183:     if(battle.hp.foe<=0)return finishBattle('player')
184:     setTimeout(enemyTurn,650)
185:   })
186: }
187: function enemyTurn() {
188:   if(!battle||battle.finished)return
189:   const choices=movesFor(battle.foe).filter(m=>m.type==='strike'&&battle.sta.foe>=m.cost)
190:   const move=choices[Math.floor(Math.random()*choices.length)]||movesFor(battle.foe).find(m=>m.type==='defend')
191:   battle.turn++; applyMove('foe','player',move,()=>{
192:     if(battle.hp.player<=0)return finishBattle('foe')
193:     battle.busy=false; renderBattle()
194:   })
195: }
196: function finishBattle(winner) {
197:   battle.finished=true; battle.winner=winner; battle.busy=false
198:   battle.player.battles=(battle.player.battles||0)+1; battle.foe.battles=(battle.foe.battles||0)+1
199:   if(winner==='player'){battle.player.wins=(battle.player.wins||0)+1;game.wins++;game.coins+=25;toast('Victory! +25 shards and a new experience point.')}else toast(`${battle.foe.name} wins this round. Your creature will be ready for another bout.`)
200:   persist(); renderBattle(); renderRoster()
201: }
202: function exitBattle() { battle=null; world.exitArena(); mode='habitat'; updateModeUI(); populateWorld(); renderBattle(); renderProfile() }
203: function dispatch(action) {
204:   if(action==='close')closeModal()
205:   else if(action==='discover')discover()
206:   else if(action==='breed')breedDialog()
207:   else if(action==='breed-confirm')breed()
208:   else if(action==='rename')renameDialog()
209:   else if(action==='rename-confirm')rename()
210:   else if(action==='arena')mode==='arena'?exitBattle():arenaDialog()
211:   else if(action==='battle-start')startBattle()
212:   else if(action==='battle-exit')exitBattle()
213:   else if(action==='sanctuary'){window.scrollTo({top:0,behavior:'smooth'});toast('Sanctuary roster is ready.')}
214:   else if(action==='habitat'){if(mode==='arena')exitBattle();else toast('You are in the Verdant Hollow.')}
215:   else if(action==='profile'){document.querySelector('.right-panel').scrollIntoView({behavior:'smooth',block:'start'})}
216: }
217: document.addEventListener('click',e=>{
218:   const action=e.target.closest('[data-action]')?.dataset.action
219:   if(action){dispatch(action);return}
220:   const creature=e.target.closest('[data-creature]')?.dataset.creature
221:   if(creature){selectCreature(creature);return}
222:   const tabButton=e.target.closest('[data-tab]')
223:   if(tabButton){tab=tabButton.dataset.tab;renderProfile();return}
224:   const careButton=e.target.closest('[data-care]')
225:   if(careButton){care(careButton.dataset.care);return}
226:   const move=e.target.closest('[data-move]')
227:   if(move){playerTurn(move.dataset.move);return}
228:   const modeButton=e.target.closest('[data-mode]')
229:   if(modeButton){if(modeButton.dataset.mode==='arena'){if(mode==='arena')return;arenaDialog()}else if(mode==='arena')exitBattle();return}
230:   if(e.target.id==='modal-layer')closeModal()
231: })
232: document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Enter'&&e.target.id==='rename-input')rename()})
233: function gameLoop(now) {
234:   const dt=Math.min(1,(now-(game.lastTick||now))/1000); game.lastTick=now
235:   if(mode==='habitat'&&dt>0){game.creatures.forEach(c=>decayNeeds(c,dt));if((game.decayTimer=(game.decayTimer||0)+dt)>7){game.decayTimer=0;renderProfile();renderRoster();persist()}}
236:   requestAnimationFrame(gameLoop)
237: }
238: window.addEventListener('beforeunload',persist)
239: persist(); renderRoster(); renderProfile(); populateWorld(); updateModeUI(); requestAnimationFrame(gameLoop)

