import {spawn} from'node:child_process';const port=9342,b=spawn('chromium',['--headless=new','--no-sandbox','--disable-dev-shm-usage','--enable-webgl','--enable-unsafe-swiftshader',`--remote-debugging-port=${port}`,'--user-data-dir=/tmp/opencode/helix-verify-profile','about:blank'],{stdio:'ignore'}),wait=ms=>new Promise(r=>setTimeout(r,ms));try{let ts;for(let i=0;i<60;i++){try{ts=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json();if(ts.some(t=>t.type==='page'))break}catch{}await wait(250)}const w=new WebSocket(ts.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>w.onopen=r);let id=0,p=new Map,errors=[];w.onmessage=e=>{let m=JSON.parse(e.data);if(m.id&&p.has(m.id)){p.get(m.id)(m);p.delete(m.id)}else if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text);else if(m.method==='Runtime.consoleAPICalled'&&m.params.type==='error')errors.push(m.params.args.map(a=>a.value||a.description).join(' '))};const send=(method,params={})=>new Promise(r=>{let n=++id;p.set(n,r);w.send(JSON.stringify({id:n,method,params}))});const ev=async expression=>{let r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.result.exceptionDetails)throw Error(r.result.exceptionDetails.exception?.description);return r.result.result?.value};await send('Page.enable');await send('Runtime.enable');await send('Page.navigate',{url:'http://127.0.0.1:3002/'});await wait(2300);await ev(`localStorage.clear();location.reload()`);await wait(1800);let states=[];const state=async(label)=>states.push([label,await ev(`({coins:document.querySelector('#coins').textContent,roster:document.querySelectorAll('.roster-card').length,modal:document.querySelector('#modal-layer').className,mode:document.querySelector('#stage-kicker').textContent,battle:document.querySelector('#battle-hud').textContent.trim().slice(0,120),result:document.querySelector('#battle-result').className,toast:document.querySelector('#toast').textContent})`)]);await state('initial');await ev(`document.querySelector('[data-action="discover"]').click()`);await wait(250);await state('discover');await ev(`document.querySelector('[data-action="breed"]').click()`);await wait(100);await state('breed dialog');await ev(`document.querySelector('[data-action="breed-confirm"]').click()`);await wait(300);await state('bred');await ev(`document.querySelector('[data-action="arena"]').click()`);await wait(100);await ev(`document.querySelector('[data-action="battle-start"]').click()`);await wait(250);await state('battle start');for(let i=0;i<24;i++){let finished=await ev(`!document.querySelector('#battle-result').classList.contains('hidden')`);if(finished)break;let moves=await ev(`[...document.querySelectorAll('[data-move]:not([disabled])')].map(b=>b.dataset.move)`);if(!moves.length){await wait(900);continue}await ev(`document.querySelector('[data-move="${moves[0]}"]').click()`);await wait(1350)}await state('battle resolution');await ev(`document.querySelector('#battle-result [data-action="battle-exit"]')?.click()`);await wait(400);await state('battle exit');console.log(JSON.stringify({states,errors},null,2));w.close()}finally{b.kill()}
